 const terminate=e.target.closest('[data-sponsor-terminate]');if(terminate){if(window.confirm('Terminate this sponsor early? A cancellation penalty and reputation loss will apply.'))await run(()=>request('/ui/sponsors/terminate','POST',{deal_id:terminate.dataset.sponsorTerminate}),'Sponsor contract terminated.');return;}
 const replySponsor=e.target.closest('[data-sponsor-reply]');if(replySponsor){const item=replySponsor.dataset.sponsorReply;const action=replySponsor.dataset.sponsorAction;const amount=action==='counter'?Number(document.querySelector(`#counter-${item}`)?.value||0):0;await run(()=>request('/ui/sponsors/reply','POST',{offer_id:item,action,counter_amount:amount}),'Sponsor proposal resolved.');return;}
 const back=e.target.closest('[data-room-back]');if(back){model.room=null;model.modal=null;render();return;}
