 const reply=e.target.closest('[data-meeting-reply]');if(reply){const r=await run(()=>request('/ui/meetings/choose','POST',{session_id:model.room.id,choice_id:reply.dataset.meetingReply}),'Dialogue choice recorded.');if(r){model.room={type:'meeting',...r};render();}return;}
 const walk=e.target.closest('[data-neg-walk]');if(walk){const r=await run(()=>request('/ui/negotiations/choose','POST',{session_id:model.room.id,action:'walk'}),'Talks concluded.');if(r){model.room={type:'negotiation',...r};render();}return;}
 const hireSpecial=e.target.closest('[data-hire-special]');if(hireSpecial){if(window.confirm('Hire this specialist? Weekly wages and signing fees will be charged.'))await run(()=>request('/ui/management/hire','POST',{kind:hireSpecial.dataset.kind,staff_id:hireSpecial.dataset.hireSpecial}),'Staff contract completed.');return;}
 const scout=e.target.closest('[data-scout-report]');if(scout){await run(()=>request('/ui/management/scout','POST',{scout_id:scout.dataset.scoutReport}),'Your scout filed a report.');return;}
 const nav=e.target.closest('[data-nav]');if(nav){changeView(nav.dataset.nav);return;}const close=e.target.closest('[data-close]');if(close||e.target.matches('[data-dismiss]')){model.modal=null;render();return;}const profile=e.target.closest('[data-profile]');if(profile){model.modal={type:'profile',id:profile.dataset.profile};render();return;}const report=e.target.closest('[data-report]');if(report){model.modal={type:'report',id:report.dataset.report};render();return;}const negotiate=e.target.closest('[data-negotiate]');if(negotiate){await openNegotiation(negotiate.dataset.negotiate);return;}const task=e.target.closest('[data-task]');if(task){try{addCreativeTask(task.dataset.task);}catch(err){notify(err.message,true);}return;}
 const hire=e.target.closest('[data-hire]');if(hire){if(window.confirm('Sign this head of creative and pay their fee?'))await run(()=>request('/ui/staff/hire','POST',{head_id:hire.dataset.hire}),'Creative head signed.');return;}
